NEW_FILES = {'facade_plan.py': '"""A facade\'s composition, decided for one face over every storey where its openings are chosen (0.238.0; the\nfactory\'s roadmap 79 and its `docs/proposals/FACADE_PLANNER.md`).\n\nWHY HERE AND NOT IN THE EMITTER. `_exterior` emits each side of each storey on its own, and `_emit_wall_run` is handed\none run with its openings already placed as fractions of it (`_opening_to_hole`), so nothing downstream of the spec can\nalign two storeys: it never sees two. A face is decided where its openings are first chosen -- a preset writing a spec,\nor a migration over the specs -- and this module is that place. The emitter stays the executor.\n\nWHAT THE LIBRARY WAS, measured (the factory\'s `docs/findings/facade_census_79/`, on the 102 buildings a themed lot can\ndraw): of the 169 first-storey openings in its 52 multi-storey buildings, 28 stood over a ground-floor opening; the\nEmpties, whose presets lay every storey on one list of bays, read 92.9 % through the same instrument. The upper storeys\nwere authored mirrored about their face\'s centre (167 of 177 openings) and the ground floors for the rooms behind them\n(135 of 321), so while the ground floor holds, stacking and symmetry trade against each other.\n\nTHE ROWS. A row is one family\'s composition, and each names where it came from -- the grammar is not invented here (the\nfactory\'s roadmap 79 forbids that, and is right to). The walker\'s references: "Align repeated architecture where\nconstruction would align it; vary the parts that would actually vary" (the factory\'s\n`docs/reference/HUMAN_AUTHORSHIP_GUIDE.md`), and the Empties\' comps (`docs/reference/EMPTIES_COMPS.md`, agreed\n2026-10-04): a rowhome is "two windows per storey, stacked on the same bays".\n\n  * `rowhome` -- two bays, each a fixed fraction off the front\'s centre, wider on a wider house. Was inline in\n    `presets.empty_rowhome` (the Empties, 0.174.0); its output is unchanged, to the byte.\n  * `midrise` -- round(width / bay) equal bays, at least two, the door in the bay nearest the lobby. Was inline in\n    `presets.empty_midrise` (0.213.0, the two-bay floor 0.217.0); unchanged, to the byte.\n  * `stack_mirrored` -- the library\'s upper storeys moved onto the openings below them, in mirrored pairs, within a bay\n    (below). The first composition this module applies to buildings it did not write.\n\nSTACK_MIRRORED, the rule (`migrate_facade_stack.py` runs it over the specs). Per face, storeys upward, each against\nthe storey below as it now stands:\n  * only an upper-storey WINDOW with no `tag` moves; every ground-floor opening, every door, breach, garage, vault\n    or tagged window stays where gameplay put it, and a window keeps its kind, width, height and sill;\n  * a window with a partner mirrored about the face\'s centre (same width) moves only WITH it, onto two openings\n    below that are each other\'s mirror; a window on the centre line only onto an opening on it; any other window\n    onto the nearest opening below; each target within `REACH` and taken once;\n  * a target is turned down when the window would leave its run (`EDGE_WALLS` wall thicknesses from each end), come\n    within `MIN_PIER` of another opening on its storey, or stand over a partition\'s junction with the wall (a room\n    wall in the window) -- the window then tries the next one, and stays when none is left;\n  * HELD, never moved: a window a den\'s drape hangs over (`lights._drapes_window`\'s test, on the spec\'s own volume),\n    any window on a wall a fire escape serves (its access opening, `FireEscape.access`), every window of a face whose\n    storey extents differ from the storey below\'s (a setback: the mirror is not the same line), and a window whose\n    mirrored partner stays -- tagged, held, or not a window -- since moving one of the two alone would break the\n    symmetry the storey was authored with;\n  * an Empty (`facade`) is left alone: its row composed it, and its spec is its preset\'s own output. Run over one,\n    the rule would move each rowhome\'s rear window over its back door -- the preset puts them in the house\'s two\n    bays on purpose.\nMeasured before it ran (`docs/findings/facade_census_79/predict.py`, its `over sym` row): 46 windows in 22 buildings\nmove, a median 2.0 m and at most 3.0, none into another room; stacking goes from 28 to 74 of 169 and every mirrored\nopening stays mirrored.\n"""\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport setbacks       # noqa: E402\nimport spec_loader    # noqa: E402\n\n#: The rows. Each names its source; a value is a call until the walker changes it.\nROWS = {\n    "rowhome": {\n        "source": "EMPTIES_COMPS.md, Family 1: two window bays a house; was inline in presets.empty_rowhome",\n        # a bay\'s centre, as a fraction of the front off its centre: the wide houses\' and the rest\n        "offset": 0.22, "offset_narrow": 0.2, "wide_from_m": 6.0,\n    },\n    "midrise": {\n        "source": "URBAN_MIDRISE_COMPS.md: regular windows; presets.MIDRISE_BAY (0.213.0), two-bay floor (0.217.0)",\n        "bay_m": 3.2, "min_bays": 2,\n    },\n}\n\n#: STACK_MIRRORED\'s dials. REACH: the one bay the library already chose (the mid-rise row\'s), so a window moves at\n#: most a bay. MIN_PIER: the least solid wall left between two openings on a storey. EDGE_WALLS: how many wall\n#: thicknesses a window keeps clear of its run\'s ends (half of one is the corner\'s own inset, `_emit_wall_run`).\nREACH = ROWS["midrise"]["bay_m"]\nMIN_PIER = 0.3\nEDGE_WALLS = 1.5\n#: Two centres this close along a face are one line: the specs\' openings are on a 0.5 m grid.\nTOL = 0.05\nDRAPE_NAME = "window_drape"\n\n\ndef bay_positions(row, width):\n    """The bay centres of `row` across a front `width` metres wide, as fractions of the front (-0.5..0.5)."""\n    r = ROWS[row]\n    if row == "rowhome":\n        bay = r["offset"] if float(width) >= r["wide_from_m"] else r["offset_narrow"]\n        return [-bay, bay]\n    if row == "midrise":\n        bays = max(r["min_bays"], int(round(float(width) / r["bay_m"])))\n        return [round((i + 0.5) / bays - 0.5, 4) for i in range(bays)]\n    raise KeyError(row)\n\n\ndef nearest(positions, toward):\n    """The index of the position nearest `toward` (the first of a tie)."""\n    return min(range(len(positions)), key=lambda i: abs(positions[i] - float(toward)))\n\n\ndef _near(x, xs):\n    return any(abs(x - y) <= TOL for y in xs)\n\n\ndef _run(spec, side, story):\n    """(run length, centre along the wall, wall line across it) of `side` on `story`, centrelines."""\n    x0, y0, x1, y1 = setbacks.storey_extent(spec, story)\n    if side in ("N", "S"):\n        return x1 - x0, (x0 + x1) / 2.0, (y1 if side == "N" else y0)\n    return y1 - y0, (y0 + y1) / 2.0, (x1 if side == "E" else x0)\n\n\ndef _junctions(spec, side, story, centre, line):\n    """Where the storey\'s partitions meet `side`, along the wall from its centre."""\n    wt = float(spec.wall_thick)\n    out = []\n    for p in spec.partitions:\n        if int(p.story) != story:\n            continue\n        a, b = sorted((float(p.start), float(p.end)))\n        if side in ("N", "S") and p.axis == "Y":\n            if (side == "N" and b >= line - wt) or (side == "S" and a <= line + wt):\n                out.append(float(p.pos) - centre)\n        elif side in ("E", "W") and p.axis == "X":\n            if (side == "E" and b >= line - wt) or (side == "W" and a <= line + wt):\n                out.append(float(p.pos) - centre)\n    return out\n\n\ndef _held(spec, d, side, story, u, w, centre, line, z):\n    """Why a window must not move, or None: a drape hangs over it, or a fire escape serves its wall."""\n    for fe in spec.fire_escapes:\n        if fe.wall == side and story in [int(s) for s in fe.served_stories]:\n            return "a fire escape serves its wall"\n    along = "x" if side in ("N", "S") else "y"\n    across = "y" if side in ("N", "S") else "x"\n    size = "size_x" if side in ("N", "S") else "size_y"\n    for v in d.get("volumes") or []:\n        if DRAPE_NAME not in str(v.get("name", "")):\n            continue\n        if (abs(float(v.get(along, 0.0)) - (centre + u)) <= max(float(v.get(size, 0.0)), w) / 2.0\n                and abs(float(v.get(across, 0.0)) - line) <= 1.0\n                and abs(float(v.get("z", 0.0)) - z) <= float(v.get("size_z", 0.0)) / 2.0 + 1.0):\n            return "a drape hangs over it"\n    return None\n\n\ndef _fits(t, w, others, run, wt, junctions):\n    if abs(t) + w / 2.0 > run / 2.0 - EDGE_WALLS * wt + 1e-9:\n        return "leaves the run"\n    for (u, ow) in others:\n        if abs(t - u) < (w + ow) / 2.0 + MIN_PIER - 1e-9:\n            return "too near another opening"\n    for j in junctions:\n        if abs(t - j) < w / 2.0 + wt / 2.0:\n            return "over a partition junction"\n    return None\n\n\ndef stack_mirrored(d, reach=REACH):\n    """Move `d`\'s upper-storey windows onto the openings below them, in mirrored pairs (the module\'s docstring), in\n    place. Returns ``(moves, held)``: ``moves`` [(wall, story, from_u, to_u)] in metres along the wall from its\n    centre, ``held`` [(wall, story, u, why)]."""\n    if d.get("facade"):\n        return [], []\n    spec = spec_loader.spec_from_dict(d)\n    grid = float(spec.grid)\n    wt = float(spec.wall_thick)\n    H = float(spec.story_height)\n\n    def snap(v):\n        return round(v / grid) * grid\n\n    rows = {}\n    for i, w in enumerate(d.get("ext_walls") or []):\n        rows[(w["wall"], int(w["story"]))] = (i, w)\n    moves, held = [], []\n    final = {}          # (side, story) -> the storey\'s opening positions as they now stand\n    for side in ("N", "S", "E", "W"):\n        stories = sorted(s for (sd, s) in rows if sd == side)\n        for story in stories:\n            if story < 1 or (side, story - 1) not in rows:\n                continue\n            i, wd = rows[(side, story)]\n            ib, _wb = rows[(side, story - 1)]\n            run, centre, line = _run(spec, side, story)\n            run_b, centre_b, _l = _run(spec, side, story - 1)\n            ops = spec.ext_walls[i].openings\n            here = [(snap(float(o.pos) * run), float(o.resolved()["width"]), o) for o in ops]\n            # the storey below AS IT NOW STANDS: a third storey stacks over the second\'s moved windows\n            below = final.get((side, story - 1),\n                              [snap(float(o.pos) * run_b) for o in spec.ext_walls[ib].openings])\n            movable, fixed = [], []\n            for j, (u, w, o) in enumerate(here):\n                if o.kind != "window" or o.tag:\n                    fixed.append((u, w))\n                    continue\n                r = o.resolved()\n                z = story * H + r["sill"] + r["height"] / 2.0\n                why = None\n                if abs(run - run_b) > 1e-6 or abs(centre - centre_b) > 1e-6:\n                    why = "the storey below stands on another extent"\n                else:\n                    why = _held(spec, d, side, story, u, w, centre, line, z)\n                if why:\n                    held.append((side, story, u, why))\n                    fixed.append((u, w))\n                else:\n                    movable.append((j, u, w))\n            # a window whose mirrored partner stays stays with it\n            keep = []\n            for (j, u, w) in movable:\n                if abs(u) > TOL and any(abs(fu + u) <= TOL and abs(fw - w) < 1e-6 for (fu, fw) in fixed):\n                    held.append((side, story, u, "its mirrored partner stays"))\n                    fixed.append((u, w))\n                else:\n                    keep.append((j, u, w))\n            movable = keep\n            if not movable:\n                final[(side, story)] = [u for (u, _w, _o) in here]\n                continue\n            junctions = _junctions(spec, side, story, centre, line)\n            # pair the movable windows: mirrored partners of one width, the centre line alone, the rest alone\n            groups, done = [], set()\n            for k, (j, u, w) in enumerate(movable):\n                if k in done:\n                    continue\n                done.add(k)\n                if abs(u) <= TOL:\n                    groups.append(((j,), (u,), w, "centre"))\n                    continue\n                m = next((m for m, (j2, u2, w2) in enumerate(movable)\n                          if m not in done and abs(u2 + u) <= TOL and abs(w2 - w) < 1e-6), None)\n                if m is None:\n                    groups.append(((j,), (u,), w, "alone"))\n                else:\n                    done.add(m)\n                    groups.append(((j, movable[m][0]), (u, movable[m][1]), w, "pair"))\n            placed = list(fixed)\n            taken = set()\n            new_u = {}\n            for (js, us, w, how) in groups:\n                if how == "pair":\n                    lo_u = min(us)\n                    cands = sorted((abs(b - lo_u), b) for b in below\n                                   if b < -TOL and _near(-b, below) and abs(b - lo_u) <= reach + 1e-9)\n                    targets = [(b, -b) for (_d, b) in cands]\n                elif how == "centre":\n                    targets = [(b,) for b in below if abs(b) <= TOL]\n                else:\n                    targets = [(b,) for (_d, b) in sorted((abs(b - us[0]), b) for b in below\n                                                          if abs(b - us[0]) <= reach + 1e-9)]\n                best = None\n                for ts in targets:\n                    if any(round(t, 3) in taken for t in ts):\n                        continue\n                    if all(_fits(t, w, placed + [(t2, w) for t2 in ts if t2 is not t], run, wt, junctions) is None\n                           for t in ts):\n                        best = ts\n                        break\n                if best is None:\n                    placed += [(u, w) for u in us]\n                    continue\n                pairs = list(zip(sorted(zip(us, js)), sorted(best)))\n                for ((u, j), t) in pairs:\n                    taken.add(round(t, 3))\n                    placed.append((t, w))\n                    if abs(t - u) > 1e-9:\n                        new_u[j] = (u, t)\n            for j, (u, t) in sorted(new_u.items()):\n                pos = round(t / run, 6)\n                assert abs(snap(pos * run) - t) < 1e-9, (side, story, t, pos)\n                wd["openings"][j]["pos"] = pos\n                moves.append((side, story, u, t))\n            final[(side, story)] = [new_u[j][1] if j in new_u else u for j, (u, _w, _o) in enumerate(here)]\n    return moves, held\n', 'migrate_facade_stack.py': '#!/usr/bin/env python3\n"""\nmigrate_facade_stack.py  --  the library\'s upper storeys stand over the openings below\n======================================================================================\nOne-shot, idempotent migration over specs/*.json for Deli Counter 0.238.0 (the\nfactory\'s roadmap 79, its `docs/proposals/FACADE_PLANNER.md`, step 3).\n\nMeasured on the library before it ran (the factory\'s\n`docs/findings/facade_census_79/`): of the 169 first-storey openings in the 52\nmulti-storey buildings a themed lot can draw, 28 stood over a ground-floor\nopening. The upper storeys had been authored mirrored about each face\'s centre,\nthe ground floors for the rooms behind them, and nothing ever asked the two to\nmeet.\n\nEach library spec -- not a Level Factory transient (`lf_*`), not an Empty,\nwhich its own row composed -- goes through `facade_plan.stack_mirrored`: an\nuntagged upper-storey window moves onto an opening of the storey below, a\nmirrored pair only together onto a mirrored pair, within a bay; every\nground-floor opening, door, breach and tagged window stays where gameplay put\nit. A spec that changed is REFURNISHED (`migrate_furnish_recipes.migrate`), so\nit stays a fixed point of furnish: a moved window moves the fixtures beside it.\n\n    python migrate_facade_stack.py            # write specs/\n    python migrate_facade_stack.py --check    # report only; exit 1 if any would change\n    python migrate_facade_stack.py --dir D    # another spec directory\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport facade_plan               # noqa: E402\nimport migrate_furnish_recipes   # noqa: E402\n\n\ndef migrate(d):\n    """Compose one spec dict\'s faces and refurnish it if a window moved, in place: ``(moves, held)``."""\n    moves, held = facade_plan.stack_mirrored(d)\n    if moves and d.get("rooms"):\n        migrate_furnish_recipes.migrate(d)\n    return moves, held\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    root = argv[argv.index("--dir") + 1] if "--dir" in argv else os.path.join(HERE, "specs")\n    changed, windows, held_n = [], 0, 0\n    for p in sorted(glob.glob(os.path.join(root, "*.json"))):\n        name = os.path.basename(p)[:-len(".json")]\n        if name.startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if not isinstance(d, dict) or "ext_walls" not in d:\n            continue\n        moves, held = migrate(d)\n        held_n += len(held)\n        if not moves:\n            continue\n        changed.append(name)\n        windows += len(moves)\n        print("  %s: %s" % (name, ", ".join("%s%d %+.2f -> %+.2f" % m for m in moves)))\n        if not check:\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(json.dumps(d, indent=1) + "\\n")\n    print("[facade_stack] %d window(s) in %d spec(s) %s; %d held where they stood"\n          % (windows, len(changed), "to move" if check else "moved", held_n))\n    return 1 if (check and changed) else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'test_facade_plan.py': '"""A facade\'s composition, decided where its openings are chosen (0.238.0; the factory\'s roadmap 79 and its\n`docs/proposals/FACADE_PLANNER.md`).\n\nMeasured on the library before this (the factory\'s `docs/findings/facade_census_79/`): of the 169 first-storey openings\nin the 52 multi-storey buildings a themed lot can draw, 28 stood over a ground-floor opening. The upper storeys had been\nauthored mirrored about each face\'s centre and the ground floors for the rooms behind them. `facade_plan` holds the\nEmpties\' two rows, which compose already, and `stack_mirrored`, which moves the library\'s untagged upper windows onto\nthe openings below them -- a mirrored pair only together, within a bay -- and leaves every ground-floor opening, door,\nbreach and tagged window where gameplay put it. `presets.make` runs it on every spec it writes, and\n`migrate_facade_stack.py` ran it over the library.\n\nFAIL ON 0.237.0: there is no `facade_plan`, deli_a01\'s first-storey east window stands at 5.5 m over nothing, and\n`presets.make("corner_deli")` writes it there. The library tests below read the specs alone, so they fail on 0.237.0\nfor that reason and not for an import.\n"""\nimport json\nimport os\nimport sys\n\nimport pytest\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n\nimport presets       # noqa: E402\nimport spec_loader   # noqa: E402\n\n\ndef _spec(name):\n    return json.load(open(os.path.join(HERE, "specs", name + ".json"), encoding="utf-8"))\n\n\ndef _u(d, side, story):\n    """The openings of `side` on `story`, in metres along the wall from its centre, as the builder cuts them."""\n    s = spec_loader.spec_from_dict(d)\n    run = s.footprint_x if side in ("N", "S") else s.footprint_y\n    for w in s.ext_walls:\n        if w.wall == side and w.story == story:\n            return sorted(round(round(o.pos * run / s.grid) * s.grid, 3) for o in w.openings)\n    return []\n\n\ndef _storey(story, side, openings):\n    return {"wall": side, "story": story, "openings": openings}\n\n\ndef _win(pos, **kw):\n    return dict({"kind": "window", "pos": pos, "width": 1.4}, **kw)\n\n\ndef _building(ground, first, **extra):\n    """A 40 x 20 m two-storey shell with one south face: `ground` and `first` are its openings."""\n    d = {"name": "t", "footprint_x": 40.0, "footprint_y": 20.0, "n_stories": 2, "story_height": 3.5,\n         "wall_thick": 0.3, "grid": 0.5, "ext_walls": [_storey(0, "S", ground), _storey(1, "S", first)]}\n    d.update(extra)\n    return d\n\n\n# -- the library, read from its specs alone ----------------------------------------------------------------------\n\ndef test_deli_a01s_first_storey_east_window_stands_over_the_ground_floors():\n    """The one window the rule moved in deli_a01: 5.5 m along the east wall, over nothing, to 7.0, over the ground\n    floor\'s window."""\n    d = _spec("deli_a01")\n    assert _u(d, "E", 0) == [-7.0, 7.0]\n    assert _u(d, "E", 1) == [7.0]\n\n\ndef test_bank_branch_a04s_front_is_stacked_and_still_mirrored():\n    """Its south face: windows at 12 m either side of a centred main door, and upstairs a pair at 10 m that now stands\n    over them."""\n    d = _spec("bank_branch_a04")\n    assert _u(d, "S", 0) == [-12.0, 0.0, 12.0]\n    assert _u(d, "S", 1) == [-12.0, 12.0]\n\n\ndef test_the_corner_deli_preset_writes_the_composed_face():\n    d = presets.make("corner_deli")\n    assert _u(d, "E", 1) == [7.0]\n\n\ndef test_the_library_is_migrated_and_the_migration_is_idempotent():\n    import migrate_facade_stack as M\n    assert M.main(["--check"]) == 0\n\n\ndef test_the_empties_are_left_as_their_rows_wrote_them():\n    """A rowhome\'s rear window stands in the other bay from its back door, on purpose."""\n    for n, a in presets.EMPTY_ROWHOMES.items():\n        assert _spec(n) == json.loads(json.dumps(presets.empty_rowhome(name=n, **a))), n\n\n\n# -- the rows ----------------------------------------------------------------------------------------------------\n\ndef test_the_rowhome_row_is_the_presets_two_bays():\n    import facade_plan as FP\n    assert FP.bay_positions("rowhome", 6.0) == [-0.22, 0.22]\n    assert FP.bay_positions("rowhome", 6.4) == [-0.22, 0.22]\n    assert FP.bay_positions("rowhome", 5.8) == [-0.2, 0.2]\n\n\n@pytest.mark.parametrize("width", [6.3, 15.0, 16.5, 18.0, 19.5, 21.0, 24.0])\ndef test_the_midrise_row_is_the_presets_bays(width):\n    import facade_plan as FP\n    bays = max(2, int(round(width / 3.2)))\n    assert FP.bay_positions("midrise", width) == [round((i + 0.5) / bays - 0.5, 4) for i in range(bays)]\n    assert presets.MIDRISE_BAY == FP.ROWS["midrise"]["bay_m"] == FP.REACH\n\n\ndef test_every_row_names_its_source():\n    import facade_plan as FP\n    assert all(r.get("source") for r in FP.ROWS.values())\n\n\n# -- stack_mirrored ----------------------------------------------------------------------------------------------\n\ndef test_a_mirrored_pair_moves_together_onto_a_mirrored_pair_below():\n    import facade_plan as FP\n    d = _building([_win(-0.3), {"kind": "door", "pos": 0.0, "tag": "main_entry"}, _win(0.3)],\n                  [_win(-0.25), _win(0.25)])\n    moves, held = FP.stack_mirrored(d)\n    assert sorted((m[2], m[3]) for m in moves) == [(-10.0, -12.0), (10.0, 12.0)]\n    assert _u(d, "S", 1) == [-12.0, 12.0]\n    assert held == []\n    assert FP.stack_mirrored(d) == ([], [])          # a second run moves nothing\n\n\ndef test_a_pair_stays_when_the_ground_floor_offers_no_mirrored_pair():\n    """Breaking the symmetry the upper storey was authored with is not this rule\'s to do."""\n    import facade_plan as FP\n    d = _building([_win(-0.3), _win(0.275)], [_win(-0.25), _win(0.25)])\n    assert FP.stack_mirrored(d) == ([], [])\n    assert _u(d, "S", 1) == [-10.0, 10.0]\n\n\ndef test_nothing_moves_further_than_a_bay():\n    import facade_plan as FP\n    d = _building([_win(-0.35), _win(0.35)], [_win(-0.25), _win(0.25)])     # 4 m away\n    assert FP.stack_mirrored(d) == ([], [])\n\n\ndef test_the_ground_floor_and_tagged_windows_stay():\n    import facade_plan as FP\n    d = _building([_win(-0.3), _win(0.3)], [_win(-0.25, tag="upper_entry"), _win(0.25, tag="upper_entry")])\n    assert FP.stack_mirrored(d) == ([], [])\n    d = _building([_win(-0.3), _win(0.3)], [_win(-0.25), _win(0.25)])\n    FP.stack_mirrored(d)\n    assert _u(d, "S", 0) == [-12.0, 12.0]\n\n\ndef test_a_window_alone_moves_onto_the_nearest_opening_below():\n    import facade_plan as FP\n    d = _building([_win(-0.3), {"kind": "door", "pos": 0.1}], [_win(-0.25)])\n    moves, _held = FP.stack_mirrored(d)\n    assert [(m[2], m[3]) for m in moves] == [(-10.0, -12.0)]\n\n\ndef test_a_window_whose_mirror_stays_stays_with_it():\n    """A tagged window or a held one keeps its mirrored partner where it is: moving one of the two alone would\n    break the symmetry the storey was authored with."""\n    import facade_plan as FP\n    d = _building([_win(-0.3), _win(0.3)], [_win(-0.25, tag="upper_entry"), _win(0.25)])\n    moves, held = FP.stack_mirrored(d)\n    assert moves == [] and [h[3] for h in held] == ["its mirrored partner stays"]\n\n\ndef test_a_partition_junction_turns_a_target_down():\n    """A room wall would stand in the window: the pair takes the next mirrored pair below, or stays."""\n    import facade_plan as FP\n    part = [{"story": 1, "axis": "Y", "pos": -12.0, "start": -10.0, "end": 0.0}]\n    d = _building([_win(-0.3), _win(0.3)], [_win(-0.25), _win(0.25)], partitions=part)\n    assert FP.stack_mirrored(d) == ([], [])\n\n\ndef test_a_draped_window_and_a_fire_escapes_wall_are_held():\n    import facade_plan as FP\n    drape = [{"name": "window_drape_s1_0", "x": -10.0, "y": -10.15, "z": 5.0, "size_x": 1.6, "size_y": 0.16,\n              "size_z": 1.6}]\n    d = _building([_win(-0.3), _win(0.3)], [_win(-0.25), _win(0.25)], volumes=drape)\n    moves, held = FP.stack_mirrored(d)\n    assert [h[3] for h in held] == ["a drape hangs over it", "its mirrored partner stays"] and moves == []\n    fe = [{"id": "fe", "wall": "S", "served_stories": [1], "along": 0.0}]\n    d = _building([_win(-0.3), _win(0.3)], [_win(-0.25), _win(0.25)], fire_escapes=fe)\n    moves, held = FP.stack_mirrored(d)\n    assert moves == [] and len(held) == 2\n\n\ndef test_an_empty_is_its_rows_and_is_not_touched():\n    import facade_plan as FP\n    d = _building([_win(-0.3), _win(0.3)], [_win(-0.25), _win(0.25)], facade=True)\n    assert FP.stack_mirrored(d) == ([], [])\n'}
CHANGELOG = "## [0.238.0] - a face's upper storeys stand over the openings below them: the facade planner's first rows\n\n**The factory's roadmap 79** (its `docs/proposals/FACADE_PLANNER.md`, steps 1 and 3). Measured first (the factory's\n`docs/findings/facade_census_79/`, off the built slots of the 102 buildings a themed lot can draw): of the 169\nfirst-storey openings in the 52 multi-storey buildings, 28 stood over a ground-floor opening, where the Empties --\nwhose presets lay every storey on one list of bays -- read 92.9 %. The upper storeys had been authored mirrored about\neach face's centre (167 of 177 openings) and the ground floors for the rooms behind them (135 of 321), and nothing\nasked the two to meet: `_exterior` emits each side of each storey on its own, and `_emit_wall_run` is handed one run\nwith its openings already placed.\n\n### Added\n- `facade_plan.py`, where a face is decided: the module a preset or a migration asks before an opening is placed.\n  `ROWS`, each naming its source -- `rowhome` (two bays, a fixed fraction off the front's centre) and `midrise`\n  (round(width / 3.2) equal bays, at least two) -- moved here from inline in `presets.empty_rowhome` and\n  `presets.empty_midrise`, their output unchanged to the byte: every Empty spec is still its preset's own output.\n  `bay_positions(row, width)`, `nearest(positions, toward)`; `presets.MIDRISE_BAY` reads the row.\n- `facade_plan.stack_mirrored(spec)`: an untagged upper-storey window moves onto an opening of the storey below as\n  it now stands -- a mirrored pair only together, onto a mirrored pair; a window on the centre line only onto an\n  opening on it; any other onto the nearest -- each within `REACH`, the mid-rise row's 3.2 m bay. A target that\n  would leave the run, come within `MIN_PIER` (0.3 m) of another opening or stand over a partition's junction with\n  the wall is turned down and the next one tried. Held where they stand: a window a drape hangs over, the windows\n  on a wall a fire escape serves, a setback storey's face, and a window whose mirrored partner stays. Every\n  ground-floor opening, door, breach, garage, vault and tagged window stays where gameplay put it, and an Empty is\n  its row's and untouched.\n- `presets.make` runs it on every spec it writes, after the holes pass and before every other, so cover and\n  furniture are laid round the windows that are built: corner_deli's first-storey east window moves from 5.5 to\n  7.0 m, over the ground floor's; auto_shop, compound, hospital and twin move theirs.\n- `migrate_facade_stack.py`: the library through it, each changed spec refurnished\n  (`migrate_furnish_recipes.migrate`), so it stays a fixed point of furnish. Run once: 69 windows in 32 specs, a\n  median 2.0 m and at most 3.0. The 22 of them in the themed pool, 46 windows, are the ones the factory's\n  `docs/findings/facade_census_79/predict.py` priced, building by building. 4 held: two under a drape, two on a fire\n  escape's wall. The refurnish moved 279 volumes and laid 283 in 31 of the 32 (bank's moved nothing): upper-storey\n  cabinets, chairs, shelves and cartons laid round the moved windows. strip_retail_a01's upstairs room lost its video\n  poker machine, and primos_pizza's gained one.\n- `facade_plan.py` is a geometry source (`build_freshness.GEOMETRY_SOURCES`).\n\n### Corrected\n- 0.237.0's entry says 54 of 288 levels across 24 staged lot missions carried a hole a player sees. The census counts\n  54 of 300 across 25 (the factory's `docs/findings/hole_frequency/`); the 288 was a count made by eye.\n\n### Tests\n- `test_facade_plan.py` (23; 22 fail on 0.237.0, the Empties' guard holding on both): deli_a01's east window and\n  bank_branch_a04's front read from the specs alone; the corner_deli preset writes the composed face; the library is\n  migrated and the migration idempotent; the Empties are their rows'; the two rows reproduce the presets' bays; a\n  pair moves together onto a mirrored pair, stays when the ground floor offers none, and never past a bay; the\n  ground floor and tagged windows stay; a window alone takes the nearest opening below; a window whose mirror stays\n  stays with it; a partition junction turns a target down; a drape and a fire escape hold their windows; an Empty is\n  not touched.\n\n"
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.237.0', 'Deli Counter 0.238.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    raw = (DC / name).read_bytes()
    if _sha(raw) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing written"
                         % (name, _sha(raw), PINS[name]))
    if b"\r\n" in raw:
        raise SystemExit("REFUSED: deli_counter/%s has CRLF endings; these edits are LF" % name)
    return raw.decode("utf-8")


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text
    for name, hunks_at in WHOLE.items():
        # the pin fixes the bytes, so each hunk is checked at its own line and applied from the bottom up
        lines = _read(name).splitlines(keepends=True)
        for i1, old, new in reversed(hunks_at):
            k = len(old.splitlines(keepends=True))
            if "".join(lines[i1:i1 + k]) != old:
                raise SystemExit("REFUSED: deli_counter/%s: line %d is not what this patch expects; nothing "
                                 "written" % (name, i1 + 1))
            lines[i1:i1 + k] = new.splitlines(keepends=True)
        out[name] = "".join(lines)
    for name in NEW_FILES:
        p = DC / name
        if p.exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = DC / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = DC / "CHANGELOG.md"
    ctext = cl.read_bytes().decode("utf-8")
    if not ctext.startswith("## [0.237.0]"):
        raise SystemExit("REFUSED: CHANGELOG.md does not open on 0.237.0; nothing written")
    for name, text in out.items():
        (DC / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (DC / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes((CHANGELOG + ctext).encode("utf-8"))
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: the suite, "
          "build.py --all, check.py" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
